source_patch:
--- a/hw/soc/rtl/soc_top.v
+++ b/hw/soc/rtl/soc_top.v
@@ -1131,13 +1131,22 @@
   // bring-up program compute an exact deadline. A real part needs an
   // always-on time base; soc_clint.v says so.
   // -------------------------------------------------------------------
+  // Isolated timing experiment: one free-running clock of MTIP latency.
+  // Not a shipping change or a radiation qualification claim.
+  wire clint_irq_timer_raw;
+  reg clint_irq_timer_sample;
+  always @(posedge clk_i or negedge rst_sys_n)
+    if (!rst_sys_n) clint_irq_timer_sample <= 1'b0;
+    else clint_irq_timer_sample <= clint_irq_timer_raw;
+  assign clint_irq_timer = clint_irq_timer_sample;
+
   soc_clint #(.TICK_DIV(1)) u_clint (
       .clk_i (clk_i), .rst_ni (rst_sys_n),
       .req_i (s_req[4]), .addr_i (s_addr), .we_i (s_we),
       .be_i (s_be), .wdata_i (s_wdata),
       .gnt_o (s_gnt[4]), .rvalid_o (s_rvalid[4]),
       .rdata_o (s_rdata_clint), .err_o (s_err[4]),
-      .irq_timer_o (clint_irq_timer),
+      .irq_timer_o (clint_irq_timer_raw),
       .irq_software_o (clint_irq_soft),
       .mt_ecc_o (clint_mt_ecc_ev)
   );
